UPDATE users SET username = COALESCE(?, username), password = COALESCE(?, password), email = COALESCE(?, email), role = COALESCE(?, role), status = COALESCE(?, status), last_seen = COALESCE(?, last_seen), storage_used = COALESCE(?, storage_used), storage_quota = COALESCE(?, storage_quota), total_storage_used = COALESCE(?, total_storage_used), updated_at = ? WHERE userId = ?;